-- ============================================================================
-- 005_name_moderation.sql
-- ============================================================================
-- The Pipeline Experiment — name validation, moderation and name privacy.
--
-- Run after 004. Additive: no existing name, link, participant or answer is
-- changed. Existing names start as "ok" and can be reviewed in the admin
-- dashboard.
--
-- Rules are enforced here, in the database, so they apply to the app *and* to
-- anyone calling the Supabase API directly (participants can't write tables;
-- every write goes through these functions).
--
--   * Names (a participant's own name, invitee names, seed sender names) must
--     pass public.px_name_problem(): length, characters, URLs/spam, and a small
--     editable term list (public.moderation_terms).
--   * Invitation landing pages show the sender's FIRST name only, and only when
--     the name is approved (name_status = 'ok') and the sender isn't suspended.
--   * Admins can flag / approve / hide / replace names and suspend participants;
--     every action is written to public.moderation_actions.

-- ---------------------------------------------------------------------------
-- Columns, tables, settings
-- ---------------------------------------------------------------------------

alter table public.participants
  add column if not exists name_status text not null default 'ok'
    check (name_status in ('ok', 'pending', 'flagged', 'hidden')),
  add column if not exists suspended_at timestamptz,
  add column if not exists suspended_reason text;

alter table public.invitations
  add column if not exists label_status text not null default 'ok'
    check (label_status in ('ok', 'flagged', 'hidden'));

-- Terms that make a name unacceptable. "word" matches a whole word (or the whole
-- name with spaces/punctuation removed, so "f u c k" is caught); "substring"
-- matches anywhere and is reserved for terms no real name contains. Many
-- short terms are deliberately absent because they occur inside real names
-- (e.g. Kshitij, Shital, Cassandra, Hassan, Analisa, Nazira; "Kike" is a common
-- nickname for Enrique). Edit in Supabase → Table editor.
create table public.moderation_terms (
  term text primary key check (term = lower(term) and term !~ '\s'),
  match text not null default 'word' check (match in ('word', 'substring')),
  kind text not null default 'profanity' check (kind in ('profanity', 'slur', 'explicit', 'reserved', 'spam'))
);

insert into public.moderation_terms (term, match, kind) values
  -- unambiguous: match anywhere
  ('fuck', 'substring', 'profanity'), ('motherfuck', 'substring', 'profanity'), ('bitch', 'substring', 'profanity'),
  ('asshole', 'substring', 'profanity'), ('nigger', 'substring', 'slur'), ('nigga', 'substring', 'slur'),
  ('faggot', 'substring', 'slur'), ('cumshot', 'substring', 'explicit'), ('blowjob', 'substring', 'explicit'),
  ('handjob', 'substring', 'explicit'), ('dildo', 'substring', 'explicit'), ('pornhub', 'substring', 'explicit'),
  ('onlyfans', 'substring', 'spam'), ('hitler', 'substring', 'slur'), ('pipeline', 'substring', 'reserved'),
  -- whole words only
  ('shit', 'word', 'profanity'), ('shithead', 'word', 'profanity'), ('cunt', 'word', 'profanity'),
  ('ass', 'word', 'profanity'), ('arse', 'word', 'profanity'), ('twat', 'word', 'profanity'),
  ('prick', 'word', 'profanity'), ('wank', 'word', 'profanity'), ('wanker', 'word', 'profanity'),
  ('bollocks', 'word', 'profanity'), ('piss', 'word', 'profanity'), ('bastard', 'word', 'profanity'),
  ('slut', 'word', 'explicit'), ('whore', 'word', 'explicit'), ('porn', 'word', 'explicit'),
  ('porno', 'word', 'explicit'), ('sex', 'word', 'explicit'), ('sexy', 'word', 'explicit'),
  ('penis', 'word', 'explicit'), ('vagina', 'word', 'explicit'), ('pussy', 'word', 'explicit'),
  ('tits', 'word', 'explicit'), ('boobs', 'word', 'explicit'), ('jizz', 'word', 'explicit'),
  ('horny', 'word', 'explicit'), ('nude', 'word', 'explicit'), ('nudes', 'word', 'explicit'),
  ('milf', 'word', 'explicit'), ('xxx', 'word', 'explicit'), ('rape', 'word', 'explicit'),
  ('rapist', 'word', 'explicit'), ('fag', 'word', 'slur'), ('retard', 'word', 'slur'),
  ('retarded', 'word', 'slur'), ('spic', 'word', 'slur'), ('chink', 'word', 'slur'),
  ('gook', 'word', 'slur'), ('tranny', 'word', 'slur'), ('wetback', 'word', 'slur'),
  ('beaner', 'word', 'slur'), ('raghead', 'word', 'slur'), ('towelhead', 'word', 'slur'),
  ('kkk', 'word', 'slur'), ('heil', 'word', 'slur'), ('kys', 'word', 'profanity'),
  ('admin', 'word', 'reserved'), ('administrator', 'word', 'reserved'), ('moderator', 'word', 'reserved'),
  ('support', 'word', 'reserved'), ('official', 'word', 'reserved'), ('null', 'word', 'reserved'),
  ('undefined', 'word', 'reserved')
on conflict (term) do nothing;

create table public.moderation_actions (
  id bigint generated always as identity primary key,
  admin_email text not null,
  target_type text not null check (target_type in ('participant', 'invitation')),
  target_id uuid not null,
  action text not null,
  old_value text,
  new_value text,
  reason text,
  created_at timestamptz not null default now()
);
create index moderation_actions_target_idx on public.moderation_actions (target_id);

update public.experiment_settings
  set value = value || '{"name_checks_per_ip_hour": 300, "name_rejects_per_ip_hour": 30}'::jsonb
  where key = 'rate_limits';

insert into public.experiment_settings (key, value, description) values
  ('name_review', '"after"',
   '"after": new names are shown right away and can be reviewed later (default). "before": names stay hidden on invitation pages until an admin approves them.')
on conflict (key) do nothing;

alter table public.moderation_terms enable row level security;
alter table public.moderation_actions enable row level security;
create policy "Admins read moderation terms" on public.moderation_terms for select to authenticated using (public.is_admin());
create policy "Admins read moderation log" on public.moderation_actions for select to authenticated using (public.is_admin());
revoke all on public.moderation_terms, public.moderation_actions from anon, authenticated;
grant select on public.moderation_terms, public.moderation_actions to authenticated;

-- ---------------------------------------------------------------------------
-- Validation
-- ---------------------------------------------------------------------------

-- Collapse whitespace and trim.
create or replace function public.px_tidy_name(p text)
returns text language sql immutable as $$
  select nullif(regexp_replace(btrim(coalesce(p, '')), '\s+', ' ', 'g'), '')
$$;

-- Returns NULL if the name is acceptable, otherwise a short reason (for admins
-- and tests; participants only ever see "Please enter a different name.").
-- Letters from any script are allowed, plus spaces, apostrophes (' ’ ʼ),
-- hyphens and periods.
create or replace function public.px_name_problem(p text)
returns text language plpgsql stable security definer set search_path = public as $$
declare
  v text := public.px_tidy_name(p);
  folded text;
  compact text;
  dedup text;
  tokens text[];
begin
  if v is null or char_length(v) > 40 then return 'length'; end if;
  -- digits and ASCII symbols other than ' - .
  if v ~ '[0-9!"#$%&()*+,/:;<=>?@\[\\\]^_`{|}~]' then return 'characters'; end if;
  -- control / invisible / formatting characters
  if v ~ '[\u0000-\u001F\u007F-\u009F\u00AD\u200B-\u200F\u2028-\u202F\u2060-\u206F\uFEFF\uFE00-\uFE0F]' then return 'characters'; end if;
  -- quote marks other than apostrophes, bullets, arrows, symbols, emoji, full-width ASCII
  if v ~ '[\u201A-\u201F\u2020-\u2027\u2030-\u205E\u2100-\u2BFF\u3000-\u303F\uFF01-\uFF5E\U0001F000-\U0001FFFF]' then return 'characters'; end if;
  -- must contain a letter, and start with one
  if v ~ '^[\s''’ʼ.\-]' or v !~ '[^\s''’ʼ.\-]' then return 'characters'; end if;
  if v ~ '(.)\1{4,}' then return 'repeat'; end if;
  if (select count(*) from regexp_matches(v, ' ', 'g')) > 5 then return 'spam'; end if;
  if lower(v) ~ '(^|\s)(www|https?)\M' or lower(v) ~ '[[:alpha:]]{2,}\.[[:alpha:]]{2,}' then return 'url'; end if;

  folded := translate(lower(v),
    'àáâãäåāăąçćčďèéêëēėęěìíîïīįıłñńňòóôõöøōőŕřśšşșťțùúûüūůűųýÿźžż',
    'aaaaaaaaacccdeeeeeeeeiiiiiiilnnnoooooooorrssssttuuuuuuuuyyzzz');
  compact := regexp_replace(folded, '[\s''’ʼ.\-]', '', 'g');
  dedup := regexp_replace(compact, '(.)\1+', '\1', 'g');
  tokens := regexp_split_to_array(folded, '[\s''’ʼ.\-]+');

  if exists (
    select 1 from public.moderation_terms t
    where (t.match = 'substring' and (strpos(compact, t.term) > 0
            -- "fuuuck": also check with repeated letters collapsed, for terms that have none
            or (t.term = regexp_replace(t.term, '(.)\1+', '\1', 'g') and strpos(dedup, t.term) > 0)))
       or (t.match = 'word' and (t.term = any(tokens) or compact = t.term))
  ) then
    return 'blocked';
  end if;
  return null;
end $$;

-- Rejected attempts are counted per IP (and capped) without aborting the
-- request, so the counter survives the rejection.
create or replace function public.px_name_gate(p text, p_key text default null)
returns text language plpgsql volatile security definer set search_path = public as $$
declare
  v_key text := public.px_hash(coalesce(p_key, public.px_client_ip()));
  v_limit integer := (public.px_setting('rate_limits') ->> 'name_rejects_per_ip_hour')::int;
begin
  if v_key is not null and v_limit is not null and (
      select count(*) from public.rate_events
      where kind = 'name_reject' and key_hash = v_key and created_at > now() - interval '1 hour') >= v_limit then
    raise exception 'rate_limited' using errcode = '22023';
  end if;
  if public.px_name_problem(p) is not null then
    if v_key is not null then insert into public.rate_events (kind, key_hash) values ('name_reject', v_key); end if;
    return null;
  end if;
  return public.px_tidy_name(p);
end $$;

-- Lets the app check a name before going further (e.g. before creating an
-- account). Returns only ok/not ok — never which rule matched.
create or replace function public.check_name(p_name text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.px_rate_limit('name_check', public.px_client_ip(), 'name_checks_per_ip_hour', interval '1 hour');
  return jsonb_build_object('ok', public.px_name_gate(p_name) is not null);
end $$;

-- ---------------------------------------------------------------------------
-- Enforce on every way a name enters the system
-- ---------------------------------------------------------------------------

alter function public.accept_invitation(text, text, boolean, boolean, text) rename to px_accept_invitation_v2;

create or replace function public.accept_invitation(
  p_token text,
  p_display_name text,
  p_research_consent boolean,
  p_marketing_consent boolean default false,
  p_device text default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_name text;
  v_result jsonb;
begin
  -- Existing participants don't submit a name here (their visit is recorded as
  -- a duplicate), so there is nothing to validate.
  if (public.px_me()).id is not null or auth.uid() is null then
    return public.px_accept_invitation_v2(p_token, p_display_name, p_research_consent, p_marketing_consent, p_device);
  end if;
  v_name := public.px_name_gate(p_display_name);
  if v_name is null then
    return jsonb_build_object('error', 'invalid_name');
  end if;
  v_result := public.px_accept_invitation_v2(p_token, v_name, p_research_consent, p_marketing_consent, p_device);
  if public.px_setting('name_review') #>> '{}' = 'before' then
    update public.participants set name_status = 'pending' where user_id = auth.uid() and deleted_at is null;
  end if;
  return v_result;
end $$;

alter function public.create_invitation(text, text, integer) rename to px_create_invitation_v2;

create or replace function public.create_invitation(
  p_value text,
  p_recipient_label text default null,
  p_response_ms integer default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
  v_label text;
begin
  if me.suspended_at is not null then
    raise exception 'suspended' using errcode = '42501';
  end if;
  if public.px_tidy_name(p_recipient_label) is not null then
    v_label := public.px_name_gate(p_recipient_label, me.id::text);
    if v_label is null then
      return jsonb_build_object('error', 'invalid_name');
    end if;
  end if;
  return public.px_create_invitation_v2(p_value, v_label, p_response_ms);
end $$;

alter function public.admin_create_seed_invitations(integer, text, text) rename to px_admin_create_seed_invitations_core;

create or replace function public.admin_create_seed_invitations(p_count integer, p_sender_name text, p_note text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  perform public.px_require_admin();
  if public.px_name_problem(p_sender_name) is not null then
    raise exception 'invalid_name' using errcode = '22023';
  end if;
  return public.px_admin_create_seed_invitations_core(p_count, public.px_tidy_name(p_sender_name), p_note);
end $$;

-- ---------------------------------------------------------------------------
-- What participants and invitees can see
-- ---------------------------------------------------------------------------

-- Invitation landing: only an approved FIRST name, never a hidden/flagged/
-- pending name, and nothing from a suspended or deleted sender.
alter function public.open_invitation(text) rename to px_open_invitation_v2;

create or replace function public.open_invitation(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v jsonb := public.px_open_invitation_v2(p_token);
  inv public.invitations;
  s public.participants;
  v_name text;
begin
  if v ->> 'state' <> 'ok' then return v; end if;
  select * into inv from public.invitations where token = p_token;
  if inv.sender_id is null then
    v_name := inv.sender_name; -- seed links: the admin's own name
  else
    select * into s from public.participants where id = inv.sender_id;
    if s.name_status = 'ok' and s.suspended_at is null and s.deleted_at is null then
      v_name := s.display_name;
    end if;
  end if;
  return v || jsonb_build_object('sender_name', nullif(split_part(coalesce(v_name, ''), ' ', 1), ''));
end $$;

-- Participant's own dashboard: hidden names are not shown back; suspension is reported.
alter function public.get_my_state() rename to px_get_my_state_v3;

create or replace function public.get_my_state()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb := public.px_get_my_state_v3();
  me public.participants := public.px_me();
begin
  if me.id is null then return v; end if;
  return jsonb_set(v, '{participant}', (v -> 'participant') || jsonb_build_object(
    'display_name', case when me.name_status = 'hidden' then null else me.display_name end,
    'name_status', me.name_status,
    'suspended', me.suspended_at is not null));
end $$;

-- Erasure also scrubs names from the moderation log.
alter function public.delete_my_data() rename to px_delete_my_data_v2;

create or replace function public.delete_my_data()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
begin
  if me.id is not null then
    update public.moderation_actions set old_value = null, new_value = null
      where target_id = me.id
         or target_id in (select id from public.invitations where sender_id = me.id);
  end if;
  return public.px_delete_my_data_v2();
end $$;

-- ---------------------------------------------------------------------------
-- Admin moderation
-- ---------------------------------------------------------------------------

create or replace function public.admin_names()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.px_require_admin();
  return jsonb_build_object(
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'display_name', p.display_name, 'name_status', p.name_status,
        'suspended_at', p.suspended_at, 'suspended_reason', p.suspended_reason,
        'depth', p.depth, 'created_at', p.created_at,
        'links', (select count(*) from public.invitations i where i.sender_id = p.id))
        order by (p.name_status <> 'ok') desc, p.created_at desc)
      from public.participants p where p.deleted_at is null), '[]'::jsonb),
    'labels', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', i.id, 'recipient_label', i.recipient_label, 'label_status', i.label_status,
        'status', i.status, 'created_at', i.created_at, 'sender_id', i.sender_id,
        'sender_name', s.display_name)
        order by (i.label_status <> 'ok') desc, i.created_at desc)
      from public.invitations i join public.participants s on s.id = i.sender_id
      where i.recipient_label is not null or i.label_status <> 'ok'), '[]'::jsonb),
    'log', coalesce((
      select jsonb_agg(row_to_json(a) order by a.created_at desc)
      from (select * from public.moderation_actions order by created_at desc limit 100) a), '[]'::jsonb),
    'name_review', public.px_setting('name_review') #>> '{}'
  );
end $$;

create or replace function public.admin_moderate(
  p_target text, p_id uuid, p_action text, p_value text default null, p_reason text default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_admin text;
  p public.participants;
  inv public.invitations;
  v_new text;
  v_old text;
begin
  perform public.px_require_admin();
  select lower(email) into v_admin from auth.users where id = auth.uid();

  if p_target = 'participant' then
    select * into p from public.participants where id = p_id for update;
    if not found then raise exception 'not_found' using errcode = '22023'; end if;
    v_old := p.display_name;
    case p_action
      when 'approve' then update public.participants set name_status = 'ok' where id = p_id;
      when 'flag' then update public.participants set name_status = 'flagged' where id = p_id;
      when 'hide' then update public.participants set name_status = 'hidden' where id = p_id;
      when 'replace' then
        if public.px_name_problem(p_value) is not null then raise exception 'invalid_name' using errcode = '22023'; end if;
        v_new := public.px_tidy_name(p_value);
        update public.participants set display_name = v_new, name_status = 'ok' where id = p_id;
      when 'suspend' then
        update public.participants set suspended_at = coalesce(suspended_at, now()), suspended_reason = p_reason where id = p_id;
        -- Their unused links stop working.
        update public.invitations set status = 'revoked', revoked_at = now()
          where sender_id = p_id and status in ('created', 'opened');
      when 'unsuspend' then update public.participants set suspended_at = null, suspended_reason = null where id = p_id;
      else raise exception 'invalid_action' using errcode = '22023';
    end case;
    if p_action not in ('replace') then v_new := null; v_old := case when p_action in ('hide', 'flag') then v_old end; end if;

  elsif p_target = 'invitation' then
    select * into inv from public.invitations where id = p_id for update;
    if not found then raise exception 'not_found' using errcode = '22023'; end if;
    v_old := inv.recipient_label;
    case p_action
      when 'approve' then update public.invitations set label_status = 'ok' where id = p_id;
      when 'flag' then update public.invitations set label_status = 'flagged' where id = p_id;
      when 'hide' then update public.invitations set recipient_label = null, label_status = 'hidden' where id = p_id;
      when 'replace' then
        if public.px_name_problem(p_value) is not null then raise exception 'invalid_name' using errcode = '22023'; end if;
        v_new := public.px_tidy_name(p_value);
        update public.invitations set recipient_label = v_new, label_status = 'ok' where id = p_id;
      else raise exception 'invalid_action' using errcode = '22023';
    end case;
    if p_action = 'approve' then v_old := null; end if;
  else
    raise exception 'invalid_target' using errcode = '22023';
  end if;

  insert into public.moderation_actions (admin_email, target_type, target_id, action, old_value, new_value, reason)
  values (v_admin, p_target, p_id, p_action, v_old, v_new, nullif(btrim(p_reason), ''));
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'px\_%' or p.proname like 'admin\_%' or p.proname in (
        'check_name', 'accept_invitation', 'create_invitation', 'open_invitation', 'get_my_state', 'delete_my_data'))
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

grant execute on function public.check_name(text) to anon, authenticated;
grant execute on function public.open_invitation(text) to anon, authenticated;
grant execute on function public.accept_invitation(text, text, boolean, boolean, text) to authenticated;
grant execute on function public.create_invitation(text, text, integer) to authenticated;
grant execute on function public.get_my_state() to authenticated;
grant execute on function public.delete_my_data() to authenticated;
grant execute on function public.px_me() to authenticated;
grant execute on function public.admin_create_seed_invitations(integer, text, text) to authenticated;
grant execute on function public.admin_revoke_invitation(uuid) to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_export(text) to authenticated;
grant execute on function public.admin_account_stats() to authenticated;
grant execute on function public.admin_names() to authenticated;
grant execute on function public.admin_moderate(text, uuid, text, text, text) to authenticated;


-- ============================================================================
-- 006_circular_strength.sql
-- ============================================================================
-- The Pipeline Experiment — Experiment D: circular connection-strength slider.
--
-- Run after 005. Additive: the three existing methods (A strength, B context,
-- C comfort) and all existing data are unchanged.
--
--   * New method "circular": a 0–100 rating given by dragging around a circle.
--     Stored like every other answer (classifications.value = '0'..'100'), so
--     existing exports and the reciprocity analysis keep working.
--   * classifications.question_version records which wording/UI produced each
--     answer ("v1" for A–C, "circular_v1" for D), set automatically.
--   * classification_events records when a question is shown and first
--     interacted with, so completion, abandonment and timing can be compared
--     across methods.
--   * Assignment stays random and balanced, but balancing now counts only from
--     when the method list last changed — otherwise a newly added method would
--     receive every new participant until it "caught up".

-- ---------------------------------------------------------------------------
-- Method, options, versions
-- ---------------------------------------------------------------------------

update public.experiment_settings
  set value = value || jsonb_build_object('circular',
        (select jsonb_agg(g::text order by g) from generate_series(0, 100) g)),
      updated_at = now()
  where key = 'method_options';

insert into public.experiment_settings (key, value, description) values
  ('question_versions', '{"strength": "v1", "context": "v1", "comfort": "v1", "circular": "circular_v1"}',
   'Version tag stored with each answer, per method. Bump when a question''s wording or UI changes.'),
  ('assignment_epoch', to_jsonb(now()),
   'Balanced assignment counts openings since this time. Updated automatically when "methods" changes.')
on conflict (key) do nothing;

-- Add D to the random-assignment pool (existing participants keep their method).
update public.experiment_settings
  set value = value || '["circular"]'::jsonb, updated_at = now()
  where key = 'methods' and not (value ? 'circular');

alter table public.classifications add column if not exists question_version text;

create or replace function public.px_set_question_version()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.question_version := coalesce(new.question_version, public.px_setting('question_versions') ->> new.method, 'v1');
  return new;
end $$;

create trigger classifications_question_version before insert on public.classifications
  for each row execute function public.px_set_question_version();

-- Answers made before this migration came from the v1 questions.
update public.classifications set question_version = 'v1' where question_version is null;

-- ---------------------------------------------------------------------------
-- Assignment: balanced since the method list last changed
-- ---------------------------------------------------------------------------

create or replace function public.px_pick_method()
returns text language sql volatile security definer set search_path = public as $$
  select m
  from jsonb_array_elements_text(public.px_setting('methods')) m
  left join (
    select assigned_method, count(*) as c from public.invitations
    where assigned_method is not null
      and coalesce(opened_at, created_at) >= coalesce((public.px_setting('assignment_epoch') #>> '{}')::timestamptz, '-infinity')
    group by 1
  ) x on x.assigned_method = m
  order by coalesce(x.c, 0), random()
  limit 1
$$;

create or replace function public.px_bump_assignment_epoch()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.key = 'methods' and new.value is distinct from old.value then
    update public.experiment_settings set value = to_jsonb(now()), updated_at = now() where key = 'assignment_epoch';
  end if;
  return new;
end $$;

create trigger experiment_settings_methods_epoch after update on public.experiment_settings
  for each row execute function public.px_bump_assignment_epoch();

-- ---------------------------------------------------------------------------
-- Comparable strength (0–1) across methods; context has none
-- ---------------------------------------------------------------------------

create or replace function public.px_strength_score(p_method text, p_value text)
returns numeric language sql immutable as $$
  select case p_method
    when 'strength' then case p_value when 'close_friend' then 1 when 'acquaintance' then 0.5 when 'weak' then 0 end
    when 'comfort' then (p_value::numeric - 1) / 4
    when 'circular' then case when p_value ~ '^\d{1,3}$' then least(p_value::numeric, 100) / 100 end
  end
$$;

-- ---------------------------------------------------------------------------
-- Shown / interacted events (for completion, abandonment and timing)
-- ---------------------------------------------------------------------------

create table public.classification_events (
  id bigint generated always as identity primary key,
  direction text not null check (direction in ('inbound', 'outbound')),
  event text not null check (event in ('shown', 'interacted')),
  method text not null,
  invitation_id uuid references public.invitations(id) on delete cascade, -- inbound: the invitation being answered
  participant_id uuid references public.participants(id) on delete cascade, -- outbound: the participant inviting
  elapsed_ms integer check (elapsed_ms is null or elapsed_ms between 0 and 3600000),
  created_at timestamptz not null default now()
);
create index classification_events_lookup_idx on public.classification_events (method, direction, event);

alter table public.classification_events enable row level security;
create policy "Admins read classification events" on public.classification_events for select to authenticated using (public.is_admin());
revoke all on public.classification_events from anon, authenticated;
grant select on public.classification_events to authenticated;

update public.experiment_settings
  set value = value || '{"classification_events_per_ip_hour": 600}'::jsonb
  where key = 'rate_limits';

-- Inbound (anyone holding an open invitation link) or outbound (a participant).
-- The method is always taken from the server, never from the client.
create or replace function public.log_classification_event(
  p_direction text, p_event text, p_token text default null, p_elapsed_ms integer default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
  me public.participants := public.px_me();
begin
  if p_event not in ('shown', 'interacted') then raise exception 'invalid_value' using errcode = '22023'; end if;
  perform public.px_rate_limit('class_event', public.px_client_ip(), 'classification_events_per_ip_hour', interval '1 hour');
  if p_direction = 'inbound' then
    select * into inv from public.invitations where token = p_token;
    if not found or inv.status not in ('created', 'opened') or inv.assigned_method is null then
      return jsonb_build_object('ok', false);
    end if;
    insert into public.classification_events (direction, event, method, invitation_id, participant_id, elapsed_ms)
    values ('inbound', p_event, inv.assigned_method, inv.id, me.id, public.px_clamp_ms(p_elapsed_ms));
  elsif p_direction = 'outbound' then
    if me.id is null then return jsonb_build_object('ok', false); end if;
    insert into public.classification_events (direction, event, method, participant_id, elapsed_ms)
    values ('outbound', p_event, me.method, me.id, public.px_clamp_ms(p_elapsed_ms));
  else
    raise exception 'invalid_value' using errcode = '22023';
  end if;
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------------------
-- Admin analytics per method (A–D comparable)
-- ---------------------------------------------------------------------------

create or replace function public.admin_method_stats()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.px_require_admin();
  return jsonb_build_object(
    'methods', coalesce((
      select jsonb_agg(row_to_json(r) order by r.method) from (
        select m.method,
          (select count(*) from public.participants p where p.method = m.method and p.deleted_at is null) as participants,
          -- inbound: one "shown" per invitation; completed = an inbound answer exists
          (select count(distinct e.invitation_id) from public.classification_events e
             where e.method = m.method and e.direction = 'inbound' and e.event = 'shown') as in_shown,
          (select count(*) from public.classifications c
             where c.method = m.method and c.direction = 'inbound'
               and exists (select 1 from public.classification_events e where e.invitation_id = c.invitation_id and e.event = 'shown')) as in_completed,
          -- outbound: each opening of the question vs answers given
          (select count(*) from public.classification_events e
             where e.method = m.method and e.direction = 'outbound' and e.event = 'shown') as out_shown,
          (select count(*) from public.classifications c where c.method = m.method and c.direction = 'outbound'
             and c.created_at >= coalesce((select min(created_at) from public.classification_events), now())) as out_completed,
          (select round(avg(public.px_strength_score(c.method, c.value)) * 100, 1) from public.classifications c
             where c.method = m.method and c.direction = 'inbound') as in_avg_strength,
          (select round(avg(public.px_strength_score(c.method, c.value)) * 100, 1) from public.classifications c
             where c.method = m.method and c.direction = 'outbound') as out_avg_strength,
          (select percentile_cont(0.5) within group (order by c.response_ms) from public.classifications c
             where c.method = m.method and c.direction = 'inbound') as in_median_ms,
          (select percentile_cont(0.5) within group (order by c.response_ms) from public.classifications c
             where c.method = m.method and c.direction = 'outbound') as out_median_ms,
          (select count(*) from public.classifications c where c.method = m.method) as answers
        from (select distinct jsonb_object_keys(public.px_setting('method_options')) as method) m
      ) r), '[]'::jsonb),
    -- Experiment D: distribution by label band and in 10-point bins
    'circular_bands', coalesce((
      select jsonb_agg(row_to_json(b) order by b.ord) from (
        select band.ord, band.label,
          count(c.*) filter (where c.direction = 'inbound') as inbound,
          count(c.*) filter (where c.direction = 'outbound') as outbound
        from (values (1, 'Not well', 0, 0), (2, 'Not very well', 1, 24), (3, 'Somewhat', 25, 49),
                     (4, 'Well', 50, 74), (5, 'Very well', 75, 100)) band(ord, label, lo, hi)
        left join public.classifications c on c.method = 'circular' and c.value::int between band.lo and band.hi
        group by band.ord, band.label) b), '[]'::jsonb),
    'circular_bins', coalesce((
      select jsonb_agg(row_to_json(b) order by b.bin) from (
        select least(c.value::int / 10, 9) * 10 as bin, count(*) as n
        from public.classifications c where c.method = 'circular' group by 1) b), '[]'::jsonb),
    -- Agreement between inviter and recipient, on the comparable 0–100 scale
    'agreement', coalesce((
      select jsonb_agg(row_to_json(a)) from (
        select o.method as sender_method, n.method as recipient_method, count(*) as pairs,
          round(avg(abs(public.px_strength_score(o.method, o.value) - public.px_strength_score(n.method, n.value))) * 100, 1) as mean_abs_gap,
          round(avg(public.px_strength_score(o.method, o.value) - public.px_strength_score(n.method, n.value)) * 100, 1) as mean_sender_minus_recipient
        from public.classifications o
        join public.classifications n on n.invitation_id = o.invitation_id and n.direction = 'inbound'
        where o.direction = 'outbound'
          and public.px_strength_score(o.method, o.value) is not null
          and public.px_strength_score(n.method, n.value) is not null
        group by 1, 2 order by 1, 2) a), '[]'::jsonb)
  );
end $$;

-- Exports: question_version + completed on classifications; events export.
alter function public.admin_export(text) rename to px_admin_export_v4;

create or replace function public.admin_export(p_kind text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
begin
  perform public.px_require_admin();
  if p_kind = 'classifications' then
    select jsonb_agg(row_to_json(r) order by r.created_at) into v from (
      select c.id as classification_id, c.invitation_id, c.direction, c.rater_id as participant_id,
        c.method, c.question_version, c.value,
        public.px_strength_score(c.method, c.value) as strength_score,
        true as completed, c.response_ms, c.created_at
      from public.classifications c) r;
    return coalesce(v, '[]'::jsonb);
  elsif p_kind = 'classification_events' then
    select jsonb_agg(row_to_json(r) order by r.created_at) into v from (
      select e.id as event_id, e.direction, e.event, e.method, e.invitation_id, e.participant_id,
        e.elapsed_ms, e.created_at,
        exists (select 1 from public.classifications c
                where (e.direction = 'inbound' and c.invitation_id = e.invitation_id and c.direction = 'inbound')
                   or (e.direction = 'outbound' and c.rater_id = e.participant_id and c.direction = 'outbound'
                       and c.created_at >= e.created_at)) as completed
      from public.classification_events e) r;
    return coalesce(v, '[]'::jsonb);
  end if;
  return public.px_admin_export_v4(p_kind);
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'px\_%' or p.proname like 'admin\_%' or p.proname = 'log_classification_event')
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

grant execute on function public.log_classification_event(text, text, text, integer) to anon, authenticated;
grant execute on function public.px_me() to authenticated;
grant execute on function public.admin_create_seed_invitations(integer, text, text) to authenticated;
grant execute on function public.admin_revoke_invitation(uuid) to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_export(text) to authenticated;
grant execute on function public.admin_account_stats() to authenticated;
grant execute on function public.admin_names() to authenticated;
grant execute on function public.admin_moderate(text, uuid, text, text, text) to authenticated;
grant execute on function public.admin_method_stats() to authenticated;


-- ============================================================================
-- 007_invited_names.sql
-- ============================================================================
-- The Pipeline Experiment — inviter-provided names, confirmed by the recipient.
--
-- Run after 006. Additive: existing participants, links and answers are kept;
-- existing participants get confirmed_name = their current name.
--
--   invitations.invited_name        the first name the inviter typed (mirrors
--                                   recipient_label, so moderation hide/replace
--                                   applies automatically)
--   participants.invited_name       what they were invited as (if anything)
--   participants.confirmed_name     what they confirmed or typed themselves
--   participants.name_was_corrected true if they changed the suggestion
--                                   (computed by the server, not the browser)
--
-- An inviter's suggestion is never treated as a verified identity: the
-- recipient must confirm it or type their own, and both go through the name
-- moderation rules. Someone who received a forwarded link can say so; that
-- doesn't accept the invitation, it stays open for the intended person.

alter table public.invitations
  add column if not exists invited_name text generated always as (recipient_label) stored,
  add column if not exists misdirected_count integer not null default 0,
  add column if not exists last_misdirected_at timestamptz;

alter table public.participants
  add column if not exists invited_name text,
  add column if not exists confirmed_name text,
  add column if not exists name_was_corrected boolean;

-- Existing participants: they typed their own name.
update public.participants p set
  confirmed_name = coalesce(p.confirmed_name, p.display_name),
  invited_name = coalesce(p.invited_name, i.recipient_label),
  name_was_corrected = case when i.recipient_label is not null and p.display_name is not null
    then lower(public.px_tidy_name(p.display_name)) <> lower(public.px_tidy_name(i.recipient_label)) end
from public.invitations i
where i.id = p.invitation_id and p.confirmed_name is null and p.deleted_at is null;

update public.experiment_settings
  set value = value || '{"misdirects_per_ip_hour": 30}'::jsonb
  where key = 'rate_limits';

-- ---------------------------------------------------------------------------
-- Landing: who the invitation is for (approved name only, open links only)
-- ---------------------------------------------------------------------------

alter function public.open_invitation(text) rename to px_open_invitation_v5;

create or replace function public.open_invitation(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v jsonb := public.px_open_invitation_v5(p_token);
  inv public.invitations;
begin
  if v ->> 'state' <> 'ok' then return v; end if;
  select * into inv from public.invitations where token = p_token;
  return v || jsonb_build_object('invited_name',
    case when inv.label_status = 'ok' then public.px_tidy_name(inv.invited_name) end);
end $$;

-- ---------------------------------------------------------------------------
-- Join: record invited vs confirmed name
-- ---------------------------------------------------------------------------

alter function public.accept_invitation(text, text, boolean, boolean, text) rename to px_accept_invitation_v5;

create or replace function public.accept_invitation(
  p_token text,
  p_display_name text,
  p_research_consent boolean,
  p_marketing_consent boolean default false,
  p_device text default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v jsonb := public.px_accept_invitation_v5(p_token, p_display_name, p_research_consent, p_marketing_consent, p_device);
  inv public.invitations;
begin
  if v ->> 'state' = 'joined' then
    select * into inv from public.invitations where token = p_token;
    update public.participants p set
      invited_name = public.px_tidy_name(inv.invited_name),
      confirmed_name = p.display_name,
      name_was_corrected = case when inv.invited_name is not null
        then lower(p.display_name) <> lower(public.px_tidy_name(inv.invited_name)) end
    where p.user_id = auth.uid() and p.invitation_id = inv.id and p.deleted_at is null and p.confirmed_name is null;
  end if;
  return v;
end $$;

-- ---------------------------------------------------------------------------
-- Forwarded links: "this wasn't meant for me"
-- ---------------------------------------------------------------------------

create or replace function public.report_wrong_recipient(p_token text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
begin
  perform public.px_rate_limit('misdirect', public.px_client_ip(), 'misdirects_per_ip_hour', interval '1 hour');
  select * into inv from public.invitations where token = p_token for update;
  if not found or inv.status not in ('created', 'opened') then
    return jsonb_build_object('ok', false);
  end if;
  -- Their answer described a different relationship than the one invited: drop it.
  delete from public.classifications where invitation_id = inv.id and direction = 'inbound' and rater_id is null;
  update public.invitations set
    misdirected_count = misdirected_count + 1,
    last_misdirected_at = now(),
    answered_at = null
  where id = inv.id;
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------------------
-- Erasure and admin
-- ---------------------------------------------------------------------------

alter function public.delete_my_data() rename to px_delete_my_data_v5;

create or replace function public.delete_my_data()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
begin
  if me.id is not null then
    update public.participants set invited_name = null, confirmed_name = null where id = me.id;
  end if;
  return public.px_delete_my_data_v5();
end $$;

alter function public.admin_account_stats() rename to px_admin_account_stats_v4;

create or replace function public.admin_account_stats()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.px_require_admin();
  return public.px_admin_account_stats_v4() || jsonb_build_object(
    'joined_with_invited_name', (select count(*) from public.participants where invited_name is not null and deleted_at is null),
    'names_confirmed', (select count(*) from public.participants where name_was_corrected = false and deleted_at is null),
    'names_corrected', (select count(*) from public.participants where name_was_corrected = true and deleted_at is null),
    'misdirected_reports', (select coalesce(sum(misdirected_count), 0) from public.invitations)
  );
end $$;

alter function public.admin_export(text) rename to px_admin_export_v5;

create or replace function public.admin_export(p_kind text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb := public.px_admin_export_v5(p_kind);
begin
  if p_kind = 'participants' then
    return coalesce((
      select jsonb_agg(r.row || jsonb_build_object(
        'user_id', p.user_id, 'invitation_id', p.invitation_id,
        'invited_name', p.invited_name, 'confirmed_name', p.confirmed_name,
        'name_was_corrected', p.name_was_corrected) order by r.ord)
      from jsonb_array_elements(v) with ordinality as r(row, ord)
      left join public.participants p on p.id = (r.row ->> 'participant_id')::uuid), '[]'::jsonb);
  elsif p_kind = 'invitations' then
    return coalesce((
      select jsonb_agg(r.row || jsonb_build_object(
        'invited_name', i.invited_name, 'misdirected_count', i.misdirected_count) order by r.ord)
      from jsonb_array_elements(v) with ordinality as r(row, ord)
      left join public.invitations i on i.id = (r.row ->> 'invitation_id')::uuid), '[]'::jsonb);
  end if;
  return v;
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'px\_%' or p.proname like 'admin\_%' or p.proname in (
        'open_invitation', 'accept_invitation', 'report_wrong_recipient', 'delete_my_data'))
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

grant execute on function public.open_invitation(text) to anon, authenticated;
grant execute on function public.accept_invitation(text, text, boolean, boolean, text) to authenticated;
grant execute on function public.report_wrong_recipient(text) to anon, authenticated;
grant execute on function public.delete_my_data() to authenticated;
grant execute on function public.px_me() to authenticated;
grant execute on function public.admin_create_seed_invitations(integer, text, text) to authenticated;
grant execute on function public.admin_revoke_invitation(uuid) to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_export(text) to authenticated;
grant execute on function public.admin_account_stats() to authenticated;
grant execute on function public.admin_names() to authenticated;
grant execute on function public.admin_moderate(text, uuid, text, text, text) to authenticated;
