-- ============================================================================
-- 008_live_invitation_tracking.sql
-- ============================================================================
-- The Pipeline Experiment — live invitation tracking.
--
-- Run after 007. Additive.
--
-- Statuses shown to the inviter (derived from existing columns):
--   Ready      link generated, not shared           (shared_at is null)
--   Pending    Share/Copy tapped                     (shared_at set)
--   Opened     a person (not a bot, not the sender) opened it   (opened_at set)
--   Connected  the recipient finished joining        (status = 'accepted')
--
-- A website can't confirm SMS/iMessage delivery: "Pending" means the inviter
-- started sharing, nothing more. Opens are only counted when the invitation
-- page's code actually runs in a browser, so link-preview fetchers that just
-- read the HTML never count; crawlers that do run code are excluded by
-- user agent; the sender's own browser is excluded; repeat visits by the same
-- browser count once.
--
-- Every step is written to invitation_events (admin-only). Inviters get live
-- updates through Supabase Realtime on their own invitation rows (RLS: a
-- participant can only read invitations they sent).

create table public.invitation_events (
  id bigint generated always as identity primary key,
  invitation_id uuid not null references public.invitations(id) on delete cascade,
  event text not null check (event in ('created', 'share_initiated', 'opened', 'bot_preview', 'sender_open', 'connected')),
  detail text,           -- share method; 'repeat' for a returning visitor
  visitor_hash text,     -- salted hash of the visitor's browser id (or IP); never raw
  created_at timestamptz not null default now()
);
create index invitation_events_invitation_idx on public.invitation_events (invitation_id, event);

alter table public.invitation_events enable row level security;
create policy "Admins read invitation events" on public.invitation_events for select to authenticated using (public.is_admin());
revoke all on public.invitation_events from anon, authenticated;
grant select on public.invitation_events to authenticated;

alter table public.invitations
  add column if not exists unique_open_count integer not null default 0;

-- ---------------------------------------------------------------------------
-- Bot / link-preview detection (user agent; deliberately conservative)
-- ---------------------------------------------------------------------------

create or replace function public.px_is_bot_ua(p_ua text)
returns boolean language sql immutable as $$
  select coalesce(p_ua, '') = ''
      or lower(p_ua) ~ '(bot|crawl|spider|slurp|preview|scanner|monitor|headlesschrome|lighthouse|facebookexternalhit|facebookcatalog|embedly|quora link|outbrain|pinterest|vkshare|whatsapp|telegram|discord|slack|linkedin|skype|bitly|applebot|google-inspectiontool|python-requests|curl/|wget|httpclient|okhttp|go-http-client|axios/)'
$$;

create or replace function public.px_request_ua()
returns text language sql stable as $$
  select nullif(current_setting('request.headers', true), '')::json ->> 'user-agent'
$$;

-- ---------------------------------------------------------------------------
-- Opening an invitation
-- ---------------------------------------------------------------------------

alter function public.open_invitation(text) rename to px_open_invitation_v7;

create or replace function public.open_invitation(p_token text, p_device text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
  sender public.participants;
  v jsonb;
  v_visitor text := public.px_hash(coalesce(nullif(p_device, ''), public.px_client_ip()));
  v_seen boolean;
begin
  select * into inv from public.invitations where token = p_token;
  if not found then
    return public.px_open_invitation_v7(p_token); -- 'invalid' (and rate limiting) as before
  end if;

  -- Link previews and crawlers: no status change, no method assignment, no names.
  if public.px_is_bot_ua(public.px_request_ua()) then
    insert into public.invitation_events (invitation_id, event, detail) values (inv.id, 'bot_preview', left(public.px_request_ua(), 120));
    return jsonb_build_object('state', 'preview');
  end if;

  -- The sender's own browser (even signed out) never counts as an open.
  if inv.sender_id is not null and p_device is not null then
    select * into sender from public.participants where id = inv.sender_id;
    if sender.device_hash is not null and sender.device_hash = public.px_hash(p_device) then
      insert into public.invitation_events (invitation_id, event) values (inv.id, 'sender_open');
      return jsonb_build_object('state', 'own');
    end if;
  end if;

  v := public.px_open_invitation_v7(p_token);

  if v ->> 'state' = 'own' then
    insert into public.invitation_events (invitation_id, event) values (inv.id, 'sender_open');
  elsif v ->> 'state' = 'ok' then
    select exists (select 1 from public.invitation_events
                   where invitation_id = inv.id and event = 'opened' and visitor_hash = v_visitor) into v_seen;
    insert into public.invitation_events (invitation_id, event, detail, visitor_hash)
    values (inv.id, 'opened', case when v_seen then 'repeat' end, v_visitor);
    if not v_seen then
      update public.invitations set unique_open_count = unique_open_count + 1 where id = inv.id;
    end if;
  end if;
  return v;
end $$;

-- ---------------------------------------------------------------------------
-- Share initiated, created, connected
-- ---------------------------------------------------------------------------

alter function public.mark_invitation_shared(uuid, text) rename to px_mark_invitation_shared_v3;

create or replace function public.mark_invitation_shared(p_invitation_id uuid, p_method text)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v jsonb := public.px_mark_invitation_shared_v3(p_invitation_id, p_method);
begin
  insert into public.invitation_events (invitation_id, event, detail) values (p_invitation_id, 'share_initiated', p_method);
  return v;
end $$;

create or replace function public.px_invitation_lifecycle_events()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'INSERT' then
    insert into public.invitation_events (invitation_id, event) values (new.id, 'created');
  elsif new.status = 'accepted' and old.status is distinct from 'accepted' then
    insert into public.invitation_events (invitation_id, event) values (new.id, 'connected');
  end if;
  return new;
end $$;

create trigger invitations_lifecycle_events after insert or update of status on public.invitations
  for each row execute function public.px_invitation_lifecycle_events();

-- ---------------------------------------------------------------------------
-- The participant's own id (for the Realtime filter) and open counts
-- ---------------------------------------------------------------------------

alter function public.get_my_state() rename to px_get_my_state_v5;

create or replace function public.get_my_state()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb := public.px_get_my_state_v5();
  me public.participants := public.px_me();
begin
  if me.id is null then return v; end if;
  return jsonb_set(v, '{participant}', (v -> 'participant') || jsonb_build_object('id', me.id));
end $$;

-- ---------------------------------------------------------------------------
-- Realtime: stream changes to invitations (RLS limits each user to their own)
-- ---------------------------------------------------------------------------

do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables
                     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'invitations') then
    execute 'alter publication supabase_realtime add table public.invitations';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- Admin
-- ---------------------------------------------------------------------------

alter function public.admin_account_stats() rename to px_admin_account_stats_v5;

create or replace function public.admin_account_stats()
returns jsonb language plpgsql stable security definer set search_path = public as $$
begin
  perform public.px_require_admin();
  return public.px_admin_account_stats_v5() || jsonb_build_object(
    'human_opens', (select count(*) from public.invitation_events where event = 'opened' and detail is null),
    'repeat_opens', (select count(*) from public.invitation_events where event = 'opened' and detail = 'repeat'),
    'bot_previews', (select count(*) from public.invitation_events where event = 'bot_preview'),
    'sender_opens', (select count(*) from public.invitation_events where event = 'sender_open')
  );
end $$;

alter function public.admin_export(text) rename to px_admin_export_v6;

create or replace function public.admin_export(p_kind text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
begin
  perform public.px_require_admin();
  if p_kind = 'invitation_events' then
    select jsonb_agg(row_to_json(r) order by r.id) into v from (
      select e.id, e.invitation_id, e.event, e.detail, e.visitor_hash, e.created_at
      from public.invitation_events e) r;
    return coalesce(v, '[]'::jsonb);
  end if;
  return public.px_admin_export_v6(p_kind);
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'px\_%' or p.proname like 'admin\_%' or p.proname in (
        'open_invitation', 'mark_invitation_shared', 'get_my_state'))
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

grant execute on function public.open_invitation(text, text) to anon, authenticated;
grant execute on function public.mark_invitation_shared(uuid, text) to authenticated;
grant execute on function public.get_my_state() to authenticated;
grant execute on function public.px_me() to authenticated;
grant execute on function public.admin_create_seed_invitations(integer, text, text) to authenticated;
grant execute on function public.admin_revoke_invitation(uuid) to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_export(text) to authenticated;
grant execute on function public.admin_account_stats() to authenticated;
grant execute on function public.admin_names() to authenticated;
grant execute on function public.admin_moderate(text, uuid, text, text, text) to authenticated;
grant execute on function public.admin_method_stats() to authenticated;


-- ============================================================================
-- 009_pipeline_community.sql
-- ============================================================================
-- The Pipeline Experiment — Pipeline Community signup.
--
-- Run after 008. Additive only: no existing rows, links or research data change.
--
-- After the mission reveal, participants can optionally leave an email and choose
-- either or both of two independent consents:
--   * research_invites — "Invite me to future Pipeline experiments."
--   * updates          — "Send me Pipeline updates and early access."
-- Each consent keeps its own exact wording, timestamp and withdrawal timestamp.
--
-- Privacy
--   * community_signups has RLS on and NO table grants: emails are never readable
--     through the REST API. Participants see their own row only via
--     get_my_account(); admins via admin_* RPCs (CSV export).
--   * One row per participant and one per email (unique). Submitting an email that
--     already belongs to someone else changes nothing and reveals nothing.
--   * delete_my_data() erases the row.
--
-- Experiment 2 readiness: admin_export('research_pool') lists only participants
-- with an active research_invites consent (participant id, email, generation),
-- without any relationship data.

-- ---------------------------------------------------------------------------
-- Table
-- ---------------------------------------------------------------------------

create table if not exists public.community_signups (
  id uuid primary key default gen_random_uuid(),
  participant_id uuid not null unique references public.participants(id) on delete cascade,
  email text not null check (email = lower(email) and email ~ '^[^\s@]+@[^\s@]+\.[^\s@]{2,}$'
                             and char_length(email) <= 254),
  research_invites boolean not null default false,
  research_invites_text text,
  research_invites_at timestamptz,
  research_invites_withdrawn_at timestamptz,
  updates boolean not null default false,
  updates_text text,
  updates_at timestamptz,
  updates_withdrawn_at timestamptz,
  source text not null default 'reveal',
  signed_up_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unsubscribed_at timestamptz
);

create unique index if not exists community_signups_email_idx on public.community_signups (email);

alter table public.community_signups enable row level security;
-- No policies and no grants: only SECURITY DEFINER functions below can touch it.
revoke all on public.community_signups from anon, authenticated;

-- "Maybe later" is remembered on the server so the screen isn't shown again on
-- another device either.
alter table public.participants
  add column if not exists community_prompt_dismissed_at timestamptz;

insert into public.experiment_settings (key, value, description) values
  ('community_consent_texts', '{
      "research_invites": "Invite me to future Pipeline experiments.",
      "updates": "Send me Pipeline updates and early access."
    }'::jsonb,
    'Exact checkbox wording for the Pipeline Community signup, stored with each consent.')
on conflict (key) do nothing;

update public.experiment_settings
  set value = value || '{"community_per_ip_hour": 20}'::jsonb
  where key = 'rate_limits' and not value ? 'community_per_ip_hour';

-- Existing early-access waitlist entries already consented to updates: carry them
-- over (the waitlist table itself is kept untouched).
insert into public.community_signups
  (participant_id, email, updates, updates_text, updates_at, source, signed_up_at)
select distinct on (w.email) w.participant_id, w.email, true, w.consent_text, w.consent_at, 'waitlist', w.consent_at
from public.waitlist w
join public.participants p on p.id = w.participant_id and p.deleted_at is null
where w.withdrawn_at is null
order by w.email, w.consent_at
on conflict do nothing;

-- ---------------------------------------------------------------------------
-- Participant RPCs
-- ---------------------------------------------------------------------------

create or replace function public.px_community_texts()
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(public.px_setting('community_consent_texts'), '{}'::jsonb)
$$;

-- Sets both preferences at once, recording timestamps only when one changes.
create or replace function public.px_community_apply(p_row public.community_signups,
                                                     p_research boolean, p_updates boolean)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  t jsonb := public.px_community_texts();
begin
  update public.community_signups set
    research_invites = p_research,
    research_invites_text = case when p_research and not p_row.research_invites
                                 then t ->> 'research_invites' else research_invites_text end,
    research_invites_at = case when p_research and not p_row.research_invites then now() else research_invites_at end,
    research_invites_withdrawn_at = case when p_research then null
                                         when p_row.research_invites then now() else research_invites_withdrawn_at end,
    updates = p_updates,
    updates_text = case when p_updates and not p_row.updates then t ->> 'updates' else updates_text end,
    updates_at = case when p_updates and not p_row.updates then now() else updates_at end,
    updates_withdrawn_at = case when p_updates then null
                                when p_row.updates then now() else updates_withdrawn_at end,
    unsubscribed_at = case when p_research or p_updates then null else coalesce(unsubscribed_at, now()) end,
    updated_at = now()
  where id = p_row.id;
end $$;

create or replace function public.join_community(p_email text, p_research_invites boolean, p_updates boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
  v_email text := lower(btrim(coalesce(p_email, '')));
  r public.community_signups;
  other uuid;
begin
  if me.id is null then
    return jsonb_build_object('error', 'not_participant');
  end if;
  -- Neither box ticked means no subscription: nothing is stored.
  if not coalesce(p_research_invites, false) and not coalesce(p_updates, false) then
    return jsonb_build_object('error', 'no_preference');
  end if;
  if v_email !~ '^[^\s@]+@[^\s@]+\.[^\s@]{2,}$' or char_length(v_email) > 254 then
    return jsonb_build_object('error', 'invalid_email');
  end if;
  perform public.px_rate_limit('community', public.px_client_ip(), 'community_per_ip_hour', interval '1 hour');

  select participant_id into other from public.community_signups
    where email = v_email and participant_id <> me.id;
  if other is not null then
    -- Already someone else's address: don't change their consents and don't
    -- reveal that it exists. Record that this participant has seen the prompt.
    update public.participants set community_prompt_dismissed_at = coalesce(community_prompt_dismissed_at, now())
      where id = me.id;
    return jsonb_build_object('ok', true);
  end if;

  insert into public.community_signups (participant_id, email)
  values (me.id, v_email)
  on conflict (participant_id) do update set email = excluded.email, updated_at = now()
  returning * into r;
  -- A fresh row starts with both consents off, so apply() stamps each one chosen.
  perform public.px_community_apply(r, coalesce(p_research_invites, false), coalesce(p_updates, false));
  return jsonb_build_object('ok', true);
end $$;

-- Change either preference later; turning both off unsubscribes (row kept with
-- withdrawal timestamps as the consent record).
create or replace function public.update_community_preferences(p_research_invites boolean, p_updates boolean)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
  r public.community_signups;
begin
  if me.id is null then
    return jsonb_build_object('error', 'not_participant');
  end if;
  select * into r from public.community_signups where participant_id = me.id;
  if r.id is null then
    return jsonb_build_object('error', 'not_subscribed');
  end if;
  perform public.px_community_apply(r, coalesce(p_research_invites, false), coalesce(p_updates, false));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.dismiss_community_prompt()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
begin
  update public.participants set community_prompt_dismissed_at = coalesce(community_prompt_dismissed_at, now())
    where id = me.id;
  return jsonb_build_object('ok', true);
end $$;

alter function public.get_my_account() rename to px_get_my_account_v4;

create or replace function public.get_my_account()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
  r public.community_signups;
begin
  if me.id is not null then
    select * into r from public.community_signups where participant_id = me.id;
  end if;
  return public.px_get_my_account_v4() || jsonb_build_object(
    'community', case when r.id is null then null else jsonb_build_object(
      'email', r.email,
      'research_invites', r.research_invites,
      'updates', r.updates,
      'subscribed', r.unsubscribed_at is null,
      'signed_up_at', r.signed_up_at) end,
    'community_prompt_dismissed', me.community_prompt_dismissed_at is not null,
    'community_consent_texts', public.px_community_texts()
  );
end $$;

alter function public.delete_my_data() rename to px_delete_my_data_v8;

create or replace function public.delete_my_data()
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
begin
  if me.id is not null then
    delete from public.community_signups where participant_id = me.id;
  end if;
  return public.px_delete_my_data_v8();
end $$;

-- ---------------------------------------------------------------------------
-- Admin
-- ---------------------------------------------------------------------------

create or replace function public.admin_community_stats()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v_eligible bigint;
begin
  perform public.px_require_admin();
  select count(*) into v_eligible from public.participants where deleted_at is null and reveal_level >= 2;
  return (
    with s as (
      select c.*, p.depth from public.community_signups c
      join public.participants p on p.id = c.participant_id and p.deleted_at is null
      where c.unsubscribed_at is null)
    select jsonb_build_object(
      'total', (select count(*) from s),
      'research_invites', (select count(*) from s where research_invites),
      'updates', (select count(*) from s where updates),
      'both', (select count(*) from s where research_invites and updates),
      'unsubscribed', (select count(*) from public.community_signups c
                       join public.participants p on p.id = c.participant_id and p.deleted_at is null
                       where c.unsubscribed_at is not null),
      'dismissed', (select count(*) from public.participants
                    where deleted_at is null and community_prompt_dismissed_at is not null
                      and id not in (select participant_id from s)),
      'eligible', v_eligible,
      'participants', (select count(*) from public.participants where deleted_at is null),
      'by_generation', coalesce((
        select jsonb_agg(jsonb_build_object('depth', g.depth, 'eligible', g.eligible, 'signups', g.signups)
                         order by g.depth)
        from (
          select p.depth,
            count(*) filter (where p.reveal_level >= 2) as eligible,
            count(s.id) as signups
          from public.participants p left join s on s.participant_id = p.id
          where p.deleted_at is null
          group by p.depth) g), '[]'::jsonb)
    ));
end $$;

alter function public.admin_export(text) rename to px_admin_export_v7;

create or replace function public.admin_export(p_kind text)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb;
begin
  perform public.px_require_admin();
  if p_kind = 'community' then
    select jsonb_agg(row_to_json(r) order by r.signed_up_at) into v from (
      select c.id, c.participant_id, p.depth, c.email,
        c.research_invites, c.research_invites_text, c.research_invites_at, c.research_invites_withdrawn_at,
        c.updates, c.updates_text, c.updates_at, c.updates_withdrawn_at,
        c.source, c.signed_up_at, c.updated_at, c.unsubscribed_at
      from public.community_signups c
      join public.participants p on p.id = c.participant_id and p.deleted_at is null) r;
    return coalesce(v, '[]'::jsonb);
  elsif p_kind = 'research_pool' then
    -- Experiment 2 contact list: active research consent only, no relationship data.
    select jsonb_agg(row_to_json(r) order by r.research_invites_at) into v from (
      select c.participant_id, c.email, p.depth, c.research_invites_at
      from public.community_signups c
      join public.participants p on p.id = c.participant_id and p.deleted_at is null
      where c.research_invites and c.unsubscribed_at is null) r;
    return coalesce(v, '[]'::jsonb);
  end if;
  return public.px_admin_export_v7(p_kind);
end $$;

-- ---------------------------------------------------------------------------
-- Privileges
-- ---------------------------------------------------------------------------

do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig from pg_proc p
    where p.pronamespace = 'public'::regnamespace
      and (p.proname like 'px\_%' or p.proname like 'admin\_%' or p.proname in (
        'join_community', 'update_community_preferences', 'dismiss_community_prompt',
        'get_my_account', 'delete_my_data'))
  loop
    execute format('revoke execute on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

grant execute on function public.join_community(text, boolean, boolean) to authenticated;
grant execute on function public.update_community_preferences(boolean, boolean) to authenticated;
grant execute on function public.dismiss_community_prompt() to authenticated;
grant execute on function public.get_my_account() to authenticated;
grant execute on function public.delete_my_data() to authenticated;
grant execute on function public.px_me() to authenticated;
grant execute on function public.admin_create_seed_invitations(integer, text, text) to authenticated;
grant execute on function public.admin_revoke_invitation(uuid) to authenticated;
grant execute on function public.admin_overview() to authenticated;
grant execute on function public.admin_export(text) to authenticated;
grant execute on function public.admin_account_stats() to authenticated;
grant execute on function public.admin_names() to authenticated;
grant execute on function public.admin_moderate(text, uuid, text, text, text) to authenticated;
grant execute on function public.admin_method_stats() to authenticated;
grant execute on function public.admin_community_stats() to authenticated;


-- ============================================================================
-- 010_multi_experiment.sql
-- ============================================================================
-- The Pipeline Experiment — multiple experiments, "First L." names, connections.
--
-- Run after 009. Additive: no participant, link, answer or token is changed or
-- removed. Everything that exists today is placed in one default experiment
-- that behaves exactly as before.
--
-- Experiments
--   * experiments: name, description, invite instruction, invites per
--     participant, participant categories, active/paused.
--   * Every invitation belongs to exactly one experiment, fixed when it is
--     created (seed links: the admin's choice; referral links: the sender's
--     experiment). Token and experiment can never change afterwards, and
--     invitations can't be deleted, so a link always resolves to the same
--     experiment and a token is never reused.
--   * Pausing stops new joins and new links; nothing is deleted.
--
-- People and participations
--   * A participant row is now one person's membership in one experiment:
--     unique (user_id, experiment_id). The same login can join several
--     experiments without a second account. Identity is the auth user (and,
--     for duplicates, the browser), never name similarity.
--   * Server functions that act on "me" resolve it inside the experiment of the
--     invitation being opened/answered/accepted (transaction-local setting
--     px.experiment); elsewhere "me" is the participation the person last
--     joined or switched to (switch_experiment).
--
-- Connections
--   * Each accepted invitation is the participant's primary referral (their
--     place in the tree). Further invitations to someone already in the same
--     experiment are recorded as secondary connections (status 'duplicate'),
--     so the full graph is kept. View: public.connections (admin export).
--
-- Names
--   * New joins and inviter-typed names use "First L." (first name and last
--     initial, e.g. "James P."), normalised on the server. Full surnames are
--     rejected. Existing names are left as they are.

-- ---------------------------------------------------------------------------
-- Experiments
-- ---------------------------------------------------------------------------

create table if not exists public.experiments (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 80),
  description text check (description is null or char_length(description) <= 600),
  invite_instruction text check (invite_instruction is null or char_length(invite_instruction) <= 200),
  invites_per_participant integer not null default 2 check (invites_per_participant between 1 and 10),
  categories jsonb not null default '[]'::jsonb check (jsonb_typeof(categories) = 'array'),
  status text not null default 'active' check (status in ('active', 'paused')),
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create unique index if not exists experiments_one_default on public.experiments (is_default) where is_default;
create unique index if not exists experiments_name_idx on public.experiments (lower(name));

alter table public.experiments enable row level security;
create policy "Admins read experiments" on public.experiments for select to authenticated using (public.is_admin());
revoke all on public.experiments from anon, authenticated;
grant select on public.experiments to authenticated;

insert into public.experiments (name, invites_per_participant, is_default)
select 'The Pipeline Experiment',
       coalesce((select (value #>> '{}')::int from public.experiment_settings where key = 'max_invites'), 2),
       true
where not exists (select 1 from public.experiments where is_default);

-- ---------------------------------------------------------------------------
-- Participations and invitations belong to an experiment
-- ---------------------------------------------------------------------------

alter table public.participants
  add column if not exists experiment_id uuid references public.experiments(id),
  add column if not exists category text check (category is null or char_length(category) <= 40),
  add column if not exists focused_at timestamptz;

alter table public.invitations
  add column if not exists experiment_id uuid references public.experiments(id);

update public.participants set experiment_id = (select id from public.experiments where is_default)
  where experiment_id is null;
update public.invitations set experiment_id = (select id from public.experiments where is_default)
  where experiment_id is null;

alter table public.participants alter column experiment_id set not null;
alter table public.invitations alter column experiment_id set not null;

-- One membership per person per experiment (was: one per person).
alter table public.participants drop constraint if exists participants_user_id_key;
create unique index if not exists participants_user_experiment_idx on public.participants (user_id, experiment_id);
create index if not exists participants_experiment_idx on public.participants (experiment_id);
create index if not exists invitations_experiment_idx on public.invitations (experiment_id);

-- Where a new row belongs: a referral link → the sender's experiment; a seed
-- link → the experiment the admin chose (px.seed_experiment); a participant →
-- the experiment of the invitation they joined through.
create or replace function public.px_default_experiment()
returns uuid language sql stable security definer set search_path = public as $$
  select id from public.experiments where is_default
$$;

create or replace function public.px_invitation_experiment()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.experiment_id := coalesce(
    new.experiment_id,
    (select experiment_id from public.participants where id = new.sender_id),
    nullif(current_setting('px.seed_experiment', true), '')::uuid,
    public.px_default_experiment());
  return new;
end $$;

create trigger invitations_experiment before insert on public.invitations
  for each row execute function public.px_invitation_experiment();

create or replace function public.px_participant_experiment()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  new.experiment_id := coalesce(
    new.experiment_id,
    (select experiment_id from public.invitations where id = new.invitation_id),
    nullif(current_setting('px.experiment', true), '')::uuid,
    public.px_default_experiment());
  return new;
end $$;

create trigger participants_experiment before insert on public.participants
  for each row execute function public.px_participant_experiment();

-- Links are permanent: same token, same experiment, never deleted.
create or replace function public.px_invitation_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if tg_op = 'DELETE' then
    raise exception 'invitations_are_permanent' using errcode = '42501';
  end if;
  if new.token is distinct from old.token or new.experiment_id is distinct from old.experiment_id then
    raise exception 'invitation_immutable' using errcode = '42501';
  end if;
  return new;
end $$;

create trigger invitations_guard before update or delete on public.invitations
  for each row execute function public.px_invitation_guard();

create or replace function public.px_participant_guard()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.experiment_id is distinct from old.experiment_id then
    raise exception 'participant_experiment_immutable' using errcode = '42501';
  end if;
  return new;
end $$;

create trigger participants_guard before update on public.participants
  for each row execute function public.px_participant_guard();

-- ---------------------------------------------------------------------------
-- "Me" is per experiment; settings can be overridden per request
-- ---------------------------------------------------------------------------

create or replace function public.px_me()
returns public.participants language sql stable security definer set search_path = public as $$
  select p.* from public.participants p
  where p.user_id = auth.uid() and p.deleted_at is null
    and (nullif(current_setting('px.experiment', true), '') is null
         or p.experiment_id = nullif(current_setting('px.experiment', true), '')::uuid)
  order by greatest(p.created_at, coalesce(p.focused_at, p.created_at)) desc
  limit 1
$$;

-- Per-experiment values (e.g. invites per participant) are passed to the
-- existing functions as transaction-local overrides: px.s_<key>.
create or replace function public.px_setting(p_key text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(
    nullif(current_setting('px.s_' || p_key, true), '')::jsonb,
    (select value from public.experiment_settings where key = p_key))
$$;

create or replace function public.px_scope(p_experiment uuid)
returns void language sql volatile security definer set search_path = public as $$
  select set_config('px.experiment', coalesce(p_experiment::text, ''), true)
$$;

create or replace function public.switch_experiment(p_experiment_id uuid)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  update public.participants set focused_at = now()
    where user_id = auth.uid() and experiment_id = p_experiment_id and deleted_at is null;
  if not found then
    raise exception 'not_participant' using errcode = '42501';
  end if;
  return jsonb_build_object('ok', true);
end $$;

-- ---------------------------------------------------------------------------
-- Names: "First L."
-- ---------------------------------------------------------------------------

-- Returns the normalised "First L." form, or NULL if the input isn't a first
-- name (one or two words) followed by a single last initial. Capitalisation
-- is tidied ("james p" → "James P."); a typed full surname is rejected.
create or replace function public.px_format_name(p text)
returns text language plpgsql immutable set search_path = public as $$
declare
  v text := public.px_tidy_name(p);
  m text[];
  f text;
  i text;
begin
  if v is null then return null; end if;
  m := regexp_match(v, '^([^\s.]+(?: [^\s.]+)?) ([^\s.''’ʼ-])\.?$');
  if m is null then return null; end if;
  f := m[1];
  i := m[2];
  if upper(i) = lower(i) or char_length(f) > 30 then return null; end if;
  if f = lower(f) or f = upper(f) then
    f := initcap(f);
  else
    f := upper(left(f, 1)) || substr(f, 2);
  end if;
  return f || ' ' || upper(i) || '.';
end $$;

-- ---------------------------------------------------------------------------
-- Opening, answering and accepting happen inside the link's experiment
-- ---------------------------------------------------------------------------

create or replace function public.px_experiment_public(e public.experiments)
returns jsonb language sql stable as $$
  select jsonb_build_object(
    'id', e.id, 'name', e.name, 'description', e.description,
    'invite_instruction', e.invite_instruction, 'categories', e.categories,
    'invites_per_participant', e.invites_per_participant,
    'status', e.status, 'is_default', e.is_default)
$$;

alter function public.open_invitation(text, text) rename to px_open_invitation_v9;

create or replace function public.open_invitation(p_token text, p_device text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
  e public.experiments;
  me public.participants;
  v jsonb;
begin
  select * into inv from public.invitations where token = p_token;
  if found then
    select * into e from public.experiments where id = inv.experiment_id;
    perform public.px_scope(e.id);
    me := public.px_me();
    -- Paused: nothing changes (no open recorded, no method assigned).
    if e.status <> 'active' and not public.px_is_bot_ua(public.px_request_ua())
       and (me.id is null or inv.accepted_by is distinct from me.id) then
      return jsonb_build_object('state', 'paused');
    end if;
  end if;
  v := public.px_open_invitation_v9(p_token, p_device);
  if v ->> 'state' = 'ok' then
    v := v || jsonb_build_object('experiment', public.px_experiment_public(e));
  end if;
  return v;
end $$;

alter function public.answer_invitation(text, text, integer) rename to px_answer_invitation_v9;

create or replace function public.answer_invitation(p_token text, p_value text, p_response_ms integer default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
begin
  select * into inv from public.invitations where token = p_token;
  if found then
    perform public.px_scope(inv.experiment_id);
    if (select status from public.experiments where id = inv.experiment_id) <> 'active' then
      raise exception 'experiment_paused' using errcode = '22023';
    end if;
  end if;
  return public.px_answer_invitation_v9(p_token, p_value, p_response_ms);
end $$;

alter function public.log_classification_event(text, text, text, integer) rename to px_log_classification_event_v9;

create or replace function public.log_classification_event(
  p_direction text, p_event text, p_token text default null, p_elapsed_ms integer default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
begin
  if p_direction = 'inbound' and p_token is not null then
    perform public.px_scope((select experiment_id from public.invitations where token = p_token));
  end if;
  return public.px_log_classification_event_v9(p_direction, p_event, p_token, p_elapsed_ms);
end $$;

alter function public.accept_invitation(text, text, boolean, boolean, text) rename to px_accept_invitation_v9;

create or replace function public.accept_invitation(
  p_token text,
  p_display_name text,
  p_research_consent boolean,
  p_marketing_consent boolean default false,
  p_device text default null,
  p_category text default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  inv public.invitations;
  e public.experiments;
  me public.participants;
  sender public.participants;
  v_name text := p_display_name;
  v_category text;
  v_device text := public.px_hash(p_device);
  v jsonb;
begin
  select * into inv from public.invitations where token = p_token;
  if auth.uid() is null or not found then
    -- not_authenticated / invalid_invitation, exactly as before
    return public.px_accept_invitation_v9(p_token, p_display_name, p_research_consent, p_marketing_consent, p_device);
  end if;

  select * into e from public.experiments where id = inv.experiment_id;
  perform public.px_scope(e.id);
  me := public.px_me();
  if e.status <> 'active' and (me.id is null or inv.accepted_by is distinct from me.id) then
    raise exception 'experiment_paused' using errcode = '22023';
  end if;

  -- New to this experiment (possibly already in another one, same account).
  if me.id is null and inv.status in ('created', 'opened') then
    v_name := public.px_format_name(p_display_name);
    if v_name is null then
      return jsonb_build_object('error', 'invalid_name_format');
    end if;
    if jsonb_array_length(e.categories) > 0 then
      select c into v_category from jsonb_array_elements_text(e.categories) c
        where lower(c) = lower(btrim(coalesce(p_category, '')));
      if v_category is null then
        return jsonb_build_object('error', 'category_required');
      end if;
    end if;
    -- Browser checks, per experiment: the sender's browser can't accept their
    -- own link, and one browser holds one membership per experiment. (The same
    -- person joining a second experiment from their own browser is fine.)
    if coalesce((public.px_setting('block_same_device'))::boolean, true) and v_device is not null then
      if inv.sender_id is not null then
        select * into sender from public.participants where id = inv.sender_id;
        if sender.device_hash = v_device then
          raise exception 'self_invite' using errcode = '22023';
        end if;
      end if;
      if exists (select 1 from public.participants
                 where device_hash = v_device and deleted_at is null and experiment_id = e.id) then
        raise exception 'device_already_joined' using errcode = '22023';
      end if;
      perform set_config('px.s_block_same_device', 'false', true);
    end if;
  end if;

  v := public.px_accept_invitation_v9(p_token, v_name, p_research_consent, p_marketing_consent, p_device);
  perform set_config('px.s_block_same_device', '', true);

  if v ->> 'state' = 'joined' then
    update public.participants p set
      category = coalesce(v_category, p.category),
      -- A link from before "First L." names carried a first name only: adding
      -- the initial to it is a confirmation, not a correction.
      name_was_corrected = case
        when p.invited_name is not null and public.px_format_name(p.invited_name) is null
             and lower(p.confirmed_name) like lower(p.invited_name) || ' _.' then false
        else p.name_was_corrected end
      where p.user_id = auth.uid() and p.invitation_id = inv.id and p.deleted_at is null;
  end if;
  return v;
end $$;

-- Referral links: the sender's experiment, its invite limit, "First L." names.
alter function public.create_invitation(text, text, integer) rename to px_create_invitation_v9;

create or replace function public.create_invitation(
  p_value text,
  p_recipient_label text default null,
  p_response_ms integer default null
)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  me public.participants := public.px_me();
  e public.experiments;
  v_label text := p_recipient_label;
  v jsonb;
begin
  if me.id is null then
    return public.px_create_invitation_v9(p_value, p_recipient_label, p_response_ms);
  end if;
  select * into e from public.experiments where id = me.experiment_id;
  perform public.px_scope(e.id);
  if e.status <> 'active' then
    raise exception 'experiment_paused' using errcode = '22023';
  end if;
  if public.px_tidy_name(p_recipient_label) is not null then
    v_label := public.px_format_name(p_recipient_label);
    if v_label is null then
      return jsonb_build_object('error', 'invalid_name_format');
    end if;
  end if;
  perform set_config('px.s_max_invites', e.invites_per_participant::text, true);
  perform set_config('px.s_max_links_total', greatest(
    coalesce((select (value #>> '{}')::int from public.experiment_settings where key = 'max_links_total'), 6),
    e.invites_per_participant * 3)::text, true);
  v := public.px_create_invitation_v9(p_value, v_label, p_response_ms);
  perform set_config('px.s_max_invites', '', true);
  perform set_config('px.s_max_links_total', '', true);
  return v;
end $$;

-- ---------------------------------------------------------------------------
-- Home screen: the current experiment, and the others this person is in
-- ---------------------------------------------------------------------------

alter function public.get_my_state() rename to px_get_my_state_v9;

create or replace function public.get_my_state()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  v jsonb := public.px_get_my_state_v9();
  me public.participants := public.px_me();
  e public.experiments;
begin
  if me.id is null then return v; end if;
  select * into e from public.experiments where id = me.experiment_id;
  v := jsonb_set(v, '{participant}', (v -> 'participant') || jsonb_build_object('category', me.category));
  return v || jsonb_build_object(
    'max_invites', e.invites_per_participant,
    'experiment', public.px_experiment_public(e),
    'experiments', (
      select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'current', x.id = e.id) order by p.created_at)
      from public.participants p join public.experiments x on x.id = p.experiment_id
      where p.user_id = auth.uid() and p.deleted_at is null),
    'network', jsonb_build_object(
      'participants', (select count(*) from public.participants where deleted_at is null and experiment_id = e.id),
      'generations', (select coalesce(max(depth), 0) from public.participants where experiment_id = e.id))
  );
end $$;

